             (Z_to_bv 64 0) (Z_to_bv 64 (TR + 8 * sz)) a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x885e4) fc None m (seg_rom asegs)).
